<script>
 import {onMount} from 'svelte';import {locale} from '$lib/i18n.js';import {page} from '$app/stores';import {goto} from '$app/navigation';import {getProject,updateProject,deleteProject,listDevices,listSites,listDeployments,listLogs,attachProjectDevice,attachProjectSite,listProjectEnvironments,createProjectEnvironment,listDatabaseServers,attachProjectDatabaseServer,detachProjectDevice,detachProjectSite,detachProjectDatabaseServer} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';
 let project=null,devices=[],assigned=[],sites=[],sitesAvailable=[],environments=[],databaseServers=[],assignedDatabases=[],deployments=[],activity=[],activeTab='overview';
 $: ru=$locale!=='en';let loading=true;let selectedDevice='';let selectedSite='';let busy=false;let newEnvironment='';let selectedDatabase='';let editName='';let editDescription='';let editing=false;
 async function load(){const [p,d,all,e,db,dep,logs]=await Promise.all([getProject($page.params.id),listDevices(),listSites(),listProjectEnvironments($page.params.id),listDatabaseServers(),listDeployments($page.params.id),listLogs(100,$page.params.id)]);if(!p.ok){notify(p.error||'Проект не найден','error');goto('/projects');return}project=p.data.project;editName=project.name;editDescription=project.description||'';assigned=p.data.devices||[];sites=p.data.sites||[];if(d.ok)devices=d.data.devices||[];if(all.ok)sitesAvailable=all.data.sites||[];if(e.ok)environments=e.data.environments||[];if(db.ok)databaseServers=db.data.servers||[];assignedDatabases=p.data.database_servers||[];if(dep.ok)deployments=dep.data.deployments||[];if(logs.ok)activity=logs.data.logs||[];loading=false}
 onMount(load);
 $: available=devices.filter(d=>d.workspace_owner_id===project?.owner_user_id&&!assigned.some(a=>a.id===d.id));
 $: availableDatabaseServers=databaseServers.filter(db=>db.workspace_owner_id===project?.owner_user_id&&!assignedDatabases.some(a=>a.id===db.id));
 $: availableSites=sitesAvailable.filter(item=>item.workspace_owner_id===project?.owner_user_id&&!sites.some(s=>s.device_id===item.device_id&&s.site_id===item.site.site_id));
 async function addDevice(){if(!selectedDevice)return;busy=true;const r=await attachProjectDevice(project.id,Number(selectedDevice));busy=false;if(r.ok){notify('Устройство добавлено','success');selectedDevice='';await load()}else notify(r.error||'Не удалось добавить устройство','error')}
 async function addSite(){if(!selectedSite)return;const [did,sid]=selectedSite.split(':');busy=true;const r=await attachProjectSite(project.id,Number(did),sid);busy=false;if(r.ok){notify('Сайт добавлен','success');selectedSite='';await load()}else notify(r.error||'Не удалось добавить сайт','error')}
 async function addDatabase(){if(!selectedDatabase)return;busy=true;const r=await attachProjectDatabaseServer(project.id,Number(selectedDatabase));busy=false;if(r.ok){notify('Database server добавлен в проект','success');selectedDatabase='';await load()}else notify(r.error||'Не удалось добавить сервер БД','error')}
 async function addEnvironment(){const name=newEnvironment.trim();if(name.length<2)return;busy=true;const r=await createProjectEnvironment(project.id,name);busy=false;if(r.ok){notify('Окружение создано','success');newEnvironment='';await load()}else notify(r.error||'Не удалось создать окружение','error')}
 async function saveProject(){const name=editName.trim();if(name.length<2||name.length>80){notify('Название проекта должно содержать 2–80 символов','error');return}busy=true;const r=await updateProject(project.id,name,editDescription);busy=false;if(r.ok){notify('Проект обновлён','success');editing=false;await load()}else notify(r.error||'Не удалось обновить проект','error')}
 async function removeProject(){if(!confirm('Удалить проект? Будут удалены только настройки группировки и привязки. Устройства, сайты, базы и их данные останутся без изменений.'))return;busy=true;const r=await deleteProject(project.id);busy=false;if(r.ok){notify('Проект удалён','success');goto('/projects')}else notify(r.error||'Не удалось удалить проект','error')}
 async function removeDevice(id){if(!confirm('Открепить устройство от проекта? Само устройство и его данные останутся без изменений.'))return;busy=true;const r=await detachProjectDevice(project.id,id);busy=false;if(r.ok){notify('Устройство откреплено','success');await load()}else notify(r.error||'Не удалось открепить устройство','error')}
 async function removeSite(deviceId,siteId){if(!confirm('Открепить сайт от проекта? Файлы и работа сайта не будут удалены.'))return;busy=true;const r=await detachProjectSite(project.id,deviceId,siteId);busy=false;if(r.ok){notify('Сайт откреплён','success');await load()}else notify(r.error||'Не удалось открепить сайт','error')}
 async function removeDatabase(id){if(!confirm('Открепить Database Server от проекта? Сервер и базы останутся без изменений.'))return;busy=true;const r=await detachProjectDatabaseServer(project.id,id);busy=false;if(r.ok){notify('Database Server откреплён','success');await load()}else notify(r.error||'Не удалось открепить сервер БД','error')}
</script>
{#if loading}<div class="empty">Загрузка…</div>{:else if project}
<div class="page-header"><div><button class="back" on:click={()=>goto('/projects')}>← Projects</button><h1 class="page-title">{project.name}</h1><p class="page-desc">{project.description||project.slug}</p></div>{#if project.can_manage}<div class="project-actions"><Button size="sm" on:click={()=>{activeTab='settings';editing=true}}>{ru?'Изменить':'Edit'}</Button><Button size="sm" variant="danger" disabled={busy} on:click={removeProject}>{ru?'Удалить проект':'Delete project'}</Button></div>{/if}</div>
<nav class="project-tabs"><button class:active={activeTab==='overview'} on:click={()=>activeTab='overview'}>{ru?'Обзор':'Overview'}</button><button class:active={activeTab==='deployments'} on:click={()=>activeTab='deployments'}>{ru?'Развёртывания':'Deployments'}</button><button class:active={activeTab==='activity'} on:click={()=>activeTab='activity'}>{ru?'Активность':'Activity'}</button><button class:active={activeTab==='source'} on:click={()=>activeTab='source'}>{ru?'Репозиторий':'Source repository'}</button><button class:active={activeTab==='settings'} on:click={()=>activeTab='settings'}>{ru?'Настройки':'Settings'}</button></nav>
{#if activeTab==='settings' && editing && project.can_manage}<section class="panel edit-panel"><label>Название проекта<input class="input" bind:value={editName} maxlength="80"/></label><label>Описание<textarea class="input" bind:value={editDescription} maxlength="255" rows="2"></textarea></label><div class="add"><Button size="sm" on:click={()=>editing=false}>Отмена</Button><Button size="sm" variant="primary" disabled={busy} on:click={saveProject}>Сохранить</Button></div></section>{:else if activeTab==='settings'}<section class="panel"><h2>{ru?'Настройки проекта':'Project settings'}</h2><p>{ru?'Измени название и описание проекта или удали его.':'Update project name and description or delete the project.'}</p>{#if project.can_manage}<Button variant="primary" on:click={()=>editing=true}>{ru?'Редактировать проект':'Edit project'}</Button>{:else}<p>{ru?'У тебя нет прав на изменение проекта.':'You do not have permission to edit this project.'}</p>{/if}</section>{/if}
{#if activeTab==='overview'}
<section class="panel environments-panel"><div class="section-head"><div><h2>Environments</h2><p>Production, Development и Staging внутри проекта</p></div>{#if project.can_manage}<div class="add"><input class="input" bind:value={newEnvironment} maxlength="64" placeholder="Новое окружение"/><Button variant="primary" disabled={busy||newEnvironment.trim().length<2} on:click={addEnvironment}>Создать</Button></div>{/if}</div>
<div class="environment-grid">{#each environments as env}<a class="environment-card" href={'/projects/'+project.id+'/environments/'+env.id}><div class="environment-top"><span class="environment-icon">▣</span>{#if env.is_protected}<span class="protected">Protected</span>{:else}<span class="environment-state">Environment</span>{/if}</div><strong>{env.name}</strong><small>{env.description||env.slug}</small><code>{env.slug}</code><span class="environment-open">Открыть окружение →</span></a>{/each}</div>
{#if !environments.length}<div class="empty compact">Окружения появятся после применения миграции базы данных.</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>Devices</h2><p>Устройства, входящие в проект</p></div>{#if project.can_manage}<div class="add"><select class="input" bind:value={selectedDevice}><option value="">Выбрать устройство</option>{#each available as d}<option value={d.id}>{d.hostname||d.device_id}</option>{/each}</select><Button variant="primary" disabled={!selectedDevice||busy} on:click={addDevice}>Добавить</Button></div>{/if}</div>
{#if assigned.length}<div class="resource-list">{#each assigned as d}<div class="resource"><a class="resource-link" href={'/devices/'+d.id+'?project_id='+project.id}><span class="resource-icon">▣</span><span><strong>{d.hostname||d.device_id}</strong><small>{d.device_id}</small></span><span class="muted">Open →</span></a>{#if project.can_manage}<Button size="sm" variant="danger" disabled={busy} on:click={()=>removeDevice(d.id)}>Открепить</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">В проект ещё не добавлены устройства.</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>Database Servers</h2><p>Серверы баз данных, подключённые к проекту</p></div>{#if project.can_manage}<div class="add"><select class="input" bind:value={selectedDatabase}><option value="">Выбрать сервер БД</option>{#each availableDatabaseServers as db}<option value={db.id}>{db.name} · {db.engine}</option>{/each}</select><Button variant="primary" disabled={!selectedDatabase||busy} on:click={addDatabase}>Добавить</Button></div>{/if}</div>
{#if assignedDatabases.length}<div class="resource-list">{#each assignedDatabases as db}<div class="resource"><a class="resource-link" href={'/databases?project_id='+project.id}><span class="resource-icon">DB</span><span><strong>{db.name}</strong><small>{db.engine} · Device #{db.device_id} · {db.status}</small></span><span class="muted">Open →</span></a>{#if project.can_manage}<Button size="sm" variant="danger" disabled={busy} on:click={()=>removeDatabase(db.id)}>Открепить</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">В проект ещё не добавлены Database Servers.</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>Websites</h2><p>Сайты, сгруппированные в проекте</p></div>{#if project.can_manage}<div class="add"><select class="input" bind:value={selectedSite}><option value="">Выбрать сайт</option>{#each availableSites as item}<option value={item.device_id+':'+item.site.site_id}>{item.device_name||'Android host'} / {item.site.site_id}</option>{/each}</select><Button variant="primary" disabled={!selectedSite||busy} on:click={addSite}>Добавить</Button></div>{/if}</div>
{#if sites.length}<div class="resource-list">{#each sites as s}<div class="resource"><a class="resource-link" href={'/sites/'+s.device_id+'/'+encodeURIComponent(s.site_id)+'?project_id='+project.id}><span class="resource-icon">◉</span><span><strong>{s.site_id}</strong><small>{s.device_name}</small></span><span class="muted">Open →</span></a>{#if project.can_manage}<Button size="sm" variant="danger" disabled={busy} on:click={()=>removeSite(s.device_id,s.site_id)}>Открепить</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">Сайты пока не добавлены.</div>{/if}</section>
{/if}
{#if activeTab==='deployments'}<section class="panel"><div class="section-head"><div><h2>{ru?'Развёртывания':'Deployments'}</h2><p>{ru?'История подтверждённых операций проекта':'Confirmed project operation history'}</p></div><span>{deployments.length}</span></div>{#if deployments.length}<div class="resource-list">{#each deployments as item}<div class="resource"><span class="resource-icon">↗</span><span><strong>{item.action?.replaceAll('_',' ')||'Deployment'}</strong><small>{item.details?.site_id||item.device||'—'} · {item.details?.commit_hash||''}</small></span><span class="muted">{item.details?.ok===false?(ru?'Ошибка':'Failed'):(ru?'Успешно':'Succeeded')} · {item.created_at?new Date(item.created_at).toLocaleString():'—'}</span></div>{/each}</div>{:else}<div class="empty compact">{ru?'Развёртываний пока нет.':'No deployments yet.'}</div>{/if}</section>{/if}
{#if activeTab==='activity'}<section class="panel"><div class="section-head"><div><h2>{ru?'Активность проекта':'Project activity'}</h2><p>{ru?'События, связанные с ресурсами проекта':'Events related to this project resources'}</p></div><span>{activity.length}</span></div>{#if activity.length}<div class="resource-list">{#each activity as item}<div class="resource"><span class="resource-icon">⌁</span><span><strong>{item.action?.replaceAll('_',' ')||'Event'}</strong><small>{item.device||'Control Plane'}</small></span><span class="muted">{item.created_at?new Date(item.created_at).toLocaleString():'—'}</span></div>{/each}</div>{:else}<div class="empty compact">{ru?'Событий пока нет.':'No activity yet.'}</div>{/if}</section>{/if}
{#if activeTab==='source'}<section class="panel"><div class="section-head"><div><h2>Source Repository</h2><p>{ru?'Связанный репозиторий проекта':'Repository connected to this project'}</p></div><span class="coming-soon">{ru?'Не подключён':'Not connected'}</span></div><div class="source-empty"><span class="resource-icon">GH</span><div><strong>{ru?'Репозиторий не привязан':'No repository linked'}</strong><small>{ru?'Официальная GitHub App уже поддерживает подключение аккаунта и просмотр доступных репозиториев. Сохранение привязки к проекту и импорт пока не реализованы.':'The official GitHub App connection and repository listing are available. Persisting a repository link to this project and repository import are not implemented yet.'}</small><a href="/settings/integrations/github">{ru?'Открыть GitHub App':'Open GitHub App'} →</a></div></div></section>{/if}
{/if}
<style>
.project-tabs{display:flex;gap:4px;overflow-x:auto;padding:4px;border:1px solid var(--border);border-radius:8px;background:var(--bg-card);margin:0 0 13px}.project-tabs button{white-space:nowrap;padding:7px 10px;border:0;border-radius:6px;background:transparent;color:var(--text-muted);font-size:10px}.project-tabs button.active{background:var(--bg-elevated);color:var(--accent)}.coming-soon{font-size:9px;color:var(--text-muted)}.source-empty{display:flex;align-items:flex-start;gap:12px;padding:12px;border:1px solid var(--border);border-radius:8px}.source-empty>div{display:grid;gap:5px}.source-empty strong{font-size:11px}.source-empty small{font-size:9px;color:var(--text-muted);line-height:1.6}.source-empty a{font-size:10px;color:var(--accent)}.project-actions{display:flex;gap:7px;align-items:center}.edit-panel{display:grid;gap:10px}.edit-panel label{display:grid;gap:6px;font-size:10px;color:#cbd5e1}.edit-panel textarea{resize:vertical}.environments-panel{margin-bottom:14px}.environment-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.environment-card{display:grid;text-decoration:none;color:inherit;gap:7px;padding:13px;border:1px solid #30343b;border-radius:8px;background:#141416}.environment-top{display:flex;justify-content:space-between;align-items:center}.environment-icon{width:28px;height:28px;display:grid;place-items:center;border-radius:7px;background:#27272a;color:#d4d4d8}.environment-open{font-size:9px;color:#a1a1aa;margin-top:4px}.environment-card strong{font-size:12px}.environment-card small,.environment-card code{font-size:9px;color:#a1a1aa}.protected{font-size:8px;color:#fbbf24}.environment-state{font-size:8px;color:#a1a1aa}.back{border:0;background:none;color:#a5b4fc;font-size:10px;margin-bottom:10px}.panel{background:#101727;border:1px solid #253149;border-radius:12px;padding:16px;margin-bottom:13px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:13px}.section-head h2{font-size:12px}.section-head p{font-size:9px;color:#64748b;margin-top:3px}.add{display:flex;gap:7px}.add select{min-width:180px}.resource-list{display:grid;gap:6px}.resource{display:flex;align-items:center;gap:10px;padding:9px;border:1px solid #253149;border-radius:8px}.resource-link{display:flex;align-items:center;gap:10px;min-width:0;flex:1;text-decoration:none;color:inherit}.resource-icon{width:27px;height:27px;display:grid;place-items:center;background:#1b2740;color:#a5b4fc;border-radius:7px}.resource span:nth-child(2){display:grid;gap:2px;flex:1}.resource strong{font-size:10px}.resource small,.muted{font-size:9px;color:#64748b}.empty.compact{padding:17px;font-size:10px}
@media(max-width:650px){.environment-grid{grid-template-columns:1fr}.section-head{align-items:stretch;flex-direction:column}.add select{min-width:0;flex:1}}
</style>